// Where each entry of an uploaded archive is extracted.
const path = require('path');

function destination(dest, entryName) {
  return path.join(dest, entryName);
}

module.exports = { destination };

const archive = require('../lib/archive-paths');

test('joins an entry', () => {
  expect(archive.destination('out', 'a.txt')).toBe('out/a.txt');
});
